contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData, bytes32 assertionId) public payable {
        require(true);

        // Calls restricted to the optimistic asserter must revert for this caller.
        bool r1; try c.requestPrice(identifier, time, ancillaryData) { r1 = false; } catch { r1 = true; }
        bool r2; try c.assertionResolvedCallback(assertionId, true) { r2 = false; } catch { r2 = true; }
        bool r3; try c.assertionDisputedCallback(assertionId) { r3 = false; } catch { r3 = true; }

        // Read-only surface must be callable by anyone.
        EscalationManagerInterface.AssertionPolicy memory pol = c.getAssertionPolicy(assertionId);
        bool disputeAllowed = c.isDisputeAllowed(assertionId, address(this));

        assert(
            r1 && r2 && r3 &&
            !pol.blockAssertion && !pol.arbitrateViaEscalationManager &&
            !pol.discardOracle && !pol.validateDisputers &&
            disputeAllowed
        );
    }

    receive() external payable {}
}

