    event PriceRequestAddedCaught(bytes32 indexed identifier, uint256 time, bytes ancillaryData);
    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        // The test contract is msg.sender for all calls on c, but it is not the
        // registered optimistic asserter (c was deployed by the checker, its
        // asserter is whatever address was passed, a fresh deployment), so
        // guarded calls are used to determine success/revert.
        bool reverted;
        try c.requestPrice(identifier, time, ancillaryData) { reverted = false; }
        catch { reverted = true; }
        address asserter = address(c.optimisticAsserter());
        if (asserter == address(this)) {
            assert(!reverted);
        } else {
            assert(reverted);
        }
    }
    receive() external payable {}
}

