contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 assertionId, bool assertedTruthfully) public payable {
        require(true);
        bool r1;
        bool r2;
        // top-level state-changing calls wrapped via try would nest; use low-level instead
        (bool ok1, ) = address(c).call(abi.encodeWithSelector(c.assertionResolvedCallback.selector, assertionId, assertedTruthfully));
        r1 = !ok1;
        (bool ok2, ) = address(c).call(abi.encodeWithSelector(c.assertionDisputedCallback.selector, assertionId));
        r2 = !ok2;
        assert(r1 && r2);
    }
    receive() external payable {}
}

