contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData, bytes32 assertionId, address disputeCaller) public payable {
        require(true);
        bool reqReverted;
        try c.requestPrice(identifier, time, ancillaryData) { reqReverted = false; } catch { reqReverted = true; }
        bool resolvedReverted;
        try c.assertionResolvedCallback(assertionId, true) { resolvedReverted = false; } catch { resolvedReverted = true; }
        bool disputedReverted;
        try c.assertionDisputedCallback(assertionId) { disputedReverted = false; } catch { disputedReverted = true; }
        bool allowed = c.isDisputeAllowed(assertionId, disputeCaller);
        C.AssertionPolicy memory policy = c.getAssertionPolicy(assertionId);
        assert(reqReverted && resolvedReverted && disputedReverted && allowed &&
            !policy.blockAssertion && !policy.arbitrateViaEscalationManager &&
            !policy.discardOracle && !policy.validateDisputers);
    }
    receive() external payable {}
}

