contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData) public payable {
        require(true);
        int256 priceBefore = c.getPrice(identifier, time, ancillaryData);
        uint256 balanceBefore = address(c).balance;
        bool reverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted = false;
        } catch {
            reverted = true;
        }
        int256 priceAfter = c.getPrice(identifier, time, ancillaryData);
        assert(reverted && priceAfter == priceBefore && address(c).balance == balanceBefore);
    }
    receive() external payable {}
}
